import {GAME_NAMES} from './catalog.ts';
import {PLUS_RULES} from './club-plus/rules.ts';
import type {PlusGame} from './club-plus/meta.ts';
import type {Game} from './state.ts';

export type HelpGame=Exclude<Game,'home'>;
export interface GameHelp {introduction:string;gettingStarted:string[];tips:string[];rules:string[];variant?:string;source?:string}
type PlusGuide=Pick<GameHelp,'introduction'|'gettingStarted'|'tips'>&{extraRules?:string[]};
const plusGuides:Record<PlusGame,PlusGuide>={
 snakes:{introduction:'A race for two to four players: reach square 100 while ladders help and snakes send you back.',gettingStarted:['Choose the player count and opponent in Setup, then start a new game.','In Play, tap Roll. The app moves your counter and applies snakes and ladders automatically.'],tips:['There is no strategic choice of destination: enjoy the changing race.','Near the finish, you need the exact roll; a larger roll does not move you.'],extraRules:['Each player has one counter, starting before square 1. Players take turns clockwise. Landing at a ladder’s foot or a snake’s head moves the counter to its other end. Passing over one has no effect. The first counter to reach 100 wins; rolling a six does not grant an extra turn.']},
 senet:{introduction:'Race five counters through thirty houses using the app’s stated reconstruction of Senet; the complete ancient rules have not survived.',gettingStarted:['Choose computer or shared-device play in Setup. The two sets begin interleaved on houses 1–10.','Tap Cast, then select a highlighted counter. House numbers show the serpentine route.'],tips:['Keep neighbours together to protect them from being swapped.','Plan a landing on house 26 and the exact casts needed for the final houses.'],extraRules:['Moves in this implementation go forward along the numbered route. A swap sends the opposing counter to the moving counter’s previous house. Bring all five counters off the board to win. Protection concerns adjacent house numbers, including across a row boundary.']},
 ur:{introduction:'A two-player race to bring seven counters through private lanes and a contested shared track.',gettingStarted:['Tap Cast to roll the four binary dice.','Tap a highlighted reserve counter to enter it, or an on-board counter to move. The route and rosettes are marked.'],tips:['The central rosette is a safe place to wait and earns another cast.','Use captures to delay a rival, but preserve opportunities to bear off exactly.'],extraRules:['A zero cast passes. Counters enter from reserve using the same full-distance counting as other moves; reserve is immediately before the first route square. Private lanes cannot be captured. Passing over occupied squares is allowed. The first player to bear off all seven counters wins.']},
 ludo:{introduction:'Bring four counters from your yard around the track and through your own home lane before the other players.',gettingStarted:['Choose the number of players in Setup and start a new game.','Roll, then tap a highlighted counter. A six can bring a yard counter onto its coloured start.'],tips:['Use safe squares when an opponent is close enough to capture.','A counter near home needs an exact roll; keeping several counters moving gives more choices.'],extraRules:['Players take turns around the table. Once a counter enters its private home lane, opponents cannot follow or capture it there. All four counters must finish for that player to win. No captures occur merely by passing another counter.']},
 dominoes:{introduction:'A two-player double-six domino table with Draw, Block and Fives variants, each with its own scoring.',gettingStarted:['Choose the variant and score target in Setup, then begin a new match.','Tap a playable tile, then choose the left or right end. Draw or Pass is offered when the rules allow it.'],tips:['Check both exposed ends before choosing a tile.','In Fives, count the exposed ends, including exposed doubles; in Draw and Block, reduce the pips left in your hand.'],extraRules:['Play alternates, one tile at a time, until a player empties their hand or the hand is blocked. In a blocked Draw or Block hand, the lower remaining pip total wins. Match scores accumulate over hands until a player reaches the selected target. A tile’s visual orientation does not change its two numbers.']},
 chinese:{introduction:'Race ten marbles across a six-pointed star into the opposite camp; hops never capture pieces.',gettingStarted:['Choose an opponent, then tap one of your marbles.','Tap a highlighted destination. A distant destination may represent an entire legal hop chain.'],tips:['Build stepping stones through the centre instead of advancing every marble in isolation.','Bring your trailing marbles forward before your leaders remove useful bridges.'],extraRules:['Each turn consists of one adjacent step or one hop chain, not a step followed by hops. A hop crosses one adjacent marble into the next empty hole along the same line. Long hops over empty gaps are not used. Players alternate turns.']},
 halma:{introduction:'A two-player race from one corner camp to the opposite one, using steps and chains of hops.',gettingStarted:['Choose the classic or compact board in Setup.','Tap a piece, then a highlighted endpoint. The app finds legal hop paths to distant endpoints.'],tips:['Keep a useful chain of stepping stones for the pieces at the back.','Fill the deepest parts of your target camp before blocking their entrances.'],extraRules:['An adjacent step and a hop chain cannot be combined in one turn. Each hop crosses one adjacent piece into the next empty square. Directions may change during a chain. Players alternate turns; ordinary progress does not earn another turn.']},
 fox:{introduction:'An asymmetric contest: thirteen geese try to trap one fox, while the fox captures enough geese to escape their net.',gettingStarted:['Choose your opponent and side in Setup. Geese move first.','Tap a piece and a highlighted destination. The printed lines determine which connections exist.'],tips:['As the geese, keep a connected front rather than offering isolated captures.','As the fox, look for jumps that create several escape routes.'],extraRules:['Geese never capture. Their forward direction is toward the top of the board; sideways and forward diagonals are legal only where a printed line exists. The fox’s capture is optional, and a turn contains at most one jump. Players alternate after each move.']},
 tafl:{introduction:'Play modern 7 × 7 Brandubh: defenders escort a king to a corner while a larger attacking force tries to capture or contain him.',gettingStarted:['Choose the opponent and side in Setup. Attackers begin.','Select a piece, then a highlighted destination. The throne and escape corners are marked.'],tips:['Defenders should create more than one route to a corner.','Attackers should coordinate a net; an isolated attacker can become a capture target.'],extraRules:['Soldiers cannot jump pieces or stop on restricted squares. Several soldiers may be captured by a single move. Ordinary board edges are not capturing partners. The king can be captured away from the throne by an attacker on each opposite side, even next to the throne; the throne itself is not hostile to him.']},
 gomoku:{introduction:'A two-player connection game: build an unbroken line of at least five stones before your opponent does.',gettingStarted:['Choose the board and opponent in Setup.','Tap an empty intersection to place your stone. Placed stones stay in place.'],tips:['Check for an immediate opposing win before starting a slower attack.','Two threats that cannot both be blocked are stronger than one long line.'],extraRules:['Players alternate one placement each; the first player starts on an empty board. Stones are never moved or captured. A filled board with no winning line is a draw.']},
 nim:{introduction:'A taking game with three rule choices: Normal Nim, Misère Nim and a single-pile Take up to three game.',gettingStarted:['Select the variant in Setup.','Choose a pile and the number to remove using the legal taking controls. Read the variant before making the final move.'],tips:['Normal Nim rewards leaving a zero exclusive-or of the pile sizes.','Misère play changes near the end, when only piles of one remain; taking the last object loses.'],extraRules:['A turn must remove at least one object and cannot affect two piles. There are no passes or random rolls. In the single-pile variant, the allowed amounts are exactly one, two or three, limited by what remains.']},
 hex:{introduction:'Place stones to connect your two opposite coloured edges. Your opponent connects the other pair.',gettingStarted:['Read the coloured edge key in Play, then tap an empty hex.','After the first placement, the second player may use Swap colours instead of placing a stone.'],tips:['Look for two ways to complete a connection rather than one easily blocked path.','Keep track of your edge colours after a swap; ownership, not the opening stone’s position, changes.'],extraRules:['Only shared hex edges connect neighbours; diagonal-looking corners alone are not extra connections. Stones remain on the board permanently. After a swap, turns continue normally with the first player placing the next stone.']},
 hearts:{introduction:'A four-player trick-taking game in which low scores win. Avoid hearts and the queen of spades, unless you can take every penalty card.',gettingStarted:['Select three cards and confirm the pass when the hand requires passing.','Tap a legal card on your turn; the app handles the other three players. Collect completed tricks and continue to the next deal.'],tips:['Try to become void in a suit so you can discard dangerous cards when it is led.','Watch who has collected penalties before attempting or preventing a moon shot.'],extraRules:['Use one standard 52-card deck, no jokers, with Ace high and 2 low. A trick contains one card from each player, clockwise. Highest card of the led suit wins and its player leads next; off-suit cards cannot win. All thirteen tricks are played. A tie for the lowest final score is a tied match in this app.']},
 spades:{introduction:'A four-player partnership game. You and North bid the number of tricks your side expects, with spades always trumping other suits.',gettingStarted:['Choose your bid, including Nil only when you intend to take no tricks.','Tap a legal card on your turn. Read the team score and bag count between deals.'],tips:['Count likely winners before bidding, including how easily short suits can be trumped.','Help a Nil partner avoid winning tricks, and avoid unnecessary overtricks when your contract is secure.'],extraRules:['Use a standard 52-card deck, with Ace high and 2 low. The player after the dealer leads the first trick. Players contribute one card each clockwise. Highest spade wins a trick containing spades; otherwise the highest card of the led suit wins. The winner leads the next trick. All thirteen tricks are played before scoring; the dealer then rotates.']},
 whist:{introduction:'A four-player partnership game: you and North try to take more than six of the thirteen tricks in each deal.',gettingStarted:['Note the exposed dealer card and the trump suit.','Play a legal card when your hand is active. Collect the trick and review the score after all thirteen tricks.'],tips:['Track the trump cards that have already been played.','When your partner is winning a trick, consider saving a stronger card for later.'],extraRules:['Use a standard 52-card deck without jokers. Deal thirteen cards to each player clockwise; the exposed trump card remains part of the dealer’s hand. Play passes clockwise, one card per player. The winner of a trick leads next, and the dealer rotates for the following deal.']},
 gin:{introduction:'A two-player rummy game: arrange your ten cards into sets and runs, then end the hand with low deadwood or Gin.',gettingStarted:['Take or pass the opening upcard as prompted. On later turns, draw stock or take the upcard.','Select a card and Discard. When offered, choose Knock or Gin to end the hand, or continue playing.'],tips:['Keep cards that can combine in more than one way, such as a pair beside a potential suited run.','Avoid discarding a card that visibly helps the opponent’s recent pickups.'],extraRules:['Use a standard deck without jokers. A card can belong to only one meld in a hand’s arrangement. The two players alternate draw-and-discard turns. A defender cannot rearrange the knocker’s chosen melds to create arbitrary new layoffs; layoffs extend those melds legally. Match scores accumulate over hands.']},
 memory:{introduction:'Reveal pairs of matching faces, either alone or competing for the most pairs.',gettingStarted:['Choose the board and play mode in Setup.','Tap one covered tile, then a second. Wait for a mismatch to turn back before trying again.'],tips:['Say the faces and positions to yourself as they appear.','A known pair is safer than guessing; in competitive play, a match keeps your turn.'],extraRules:['A tile cannot be paired with itself, and already matched tiles cannot be selected again. In solo play the goal is to find every pair; in competitive play each pair is worth one and the highest total wins, with a tie possible.']},
 kakuro:{introduction:'A crossing-sums puzzle. Place digits so every across and down run has its required total without repeated digits.',gettingStarted:['Tap an empty white square, then a digit in the number pad.','Use Notes for possibilities. Fixed starter digits are clues and cannot be changed.'],tips:['A two-cell sum of 3 must use 1 and 2; a sum of 17 must use 8 and 9.','Intersect the possibilities from the across and down runs instead of solving each run in isolation.'],extraRules:['Across clues apply to the uninterrupted run of white cells to their right; down clues apply below. Black clue squares do not receive digits. Solve by satisfying every run, not by reaching a score or beating a timer.']},
 slitherlink:{introduction:'Turn edge clues into one closed loop, with no branches or disconnected extra loops.',gettingStarted:['Tap an available lattice edge to cycle line, cross and blank.','Use crosses to record edges you have ruled out. Fixed starter edges cannot be changed.'],tips:['A zero rules out all four surrounding edges.','At every used lattice point exactly two loop edges must meet; avoid closing a small loop before the rest can connect.'],extraRules:['A numbered cell may lie inside or outside the final loop. Cross marks are notes and are not loop edges. A solution must be nonempty and connected as well as satisfying all visible cell counts.']},
 hashi:{introduction:'Join numbered islands into one connected bridge network, with the correct number of bridge strands at every island.',gettingStarted:['Select two aligned nearest islands, or tap an existing bridge, to cycle its bridge count.','Use the island totals to see which connections still need strands.'],tips:['An island at a corner has fewer directions to choose from.','Do not complete a small isolated group if other islands still need to join it.'],extraRules:['A double bridge contributes two to each endpoint. Islands separated by another island are not direct neighbours. The puzzle is solved only when every island total and the overall connectivity requirement hold together.']},
 futoshiki:{introduction:'A Latin-square puzzle: every row and column contains the full digit set, with inequalities narrowing the choices.',gettingStarted:['Choose a square and enter a digit from the number pad.','Use Notes while comparing the inequality signs and fixed starter digits.'],tips:['The pointed end of an inequality faces the smaller value.','Follow chains of signs: a chain of four increasing cells needs four distinct increasing values.'],extraRules:['For an N × N board, the allowed digits are 1 through N. An inequality constrains the two cells immediately beside it. Starting digits are fixed. A completed board must satisfy both Latin-square uniqueness and every inequality.']},
 skyscrapers:{introduction:'Arrange building heights in a Latin square, then use the edge clues to check each skyline.',gettingStarted:['Tap a square and enter a height using the number pad.','Read each edge clue looking from that side into the corresponding row or column.'],tips:['A clue of 1 puts the tallest building nearest that clue.','The tallest building is always visible, and everything shorter behind it is hidden from that direction.'],extraRules:['Visibility is counted by scanning inward: a building is visible only if it is taller than every earlier building on that sightline. Each supplied clue is independent; clues from opposite ends can both constrain the same line.']},
 tangrams:{introduction:'Reassemble a silhouette using all seven pieces of a classic tangram set.',gettingStarted:['Select a piece, then drag it or use the large nudge controls.','Rotate in 45-degree steps and flip the parallelogram when necessary. Fill the displayed silhouette.'],tips:['Begin with long straight edges or obvious corners.','Use the two large triangles to reason about the remaining area before placing the small pieces.'],extraRules:['The seven pieces are two large triangles, one medium triangle, two small triangles, a square and a parallelogram. Every piece must be used, pieces cannot overlap, and their union must cover the silhouette. Their colours and original piece positions are not constraints.']},
 wordsearch:{introduction:'Find all the listed words hidden in a themed letter grid.',gettingStarted:['Choose a collection in Setup and start a puzzle.','Drag between a word’s first and last letters, or tap its two endpoints.'],tips:['Look for unusual letters or pairs of letters in a word.','Search backwards as well as forwards, including both diagonal directions.'],extraRules:['A word must follow a single straight line through adjacent cells, without turning or wrapping across the board boundary. Words may share letters. Find every listed word to finish; finding unrelated extra words does not complete the puzzle.']},
};

const make=(introduction:string,gettingStarted:string[],tips:string[],rules:string[],variant?:string,source?:string):GameHelp=>({introduction,gettingStarted,tips,rules,variant,source});
const nativeGuides:Record<Exclude<HelpGame,PlusGame>,GameHelp>={
 four:make('A two-player gravity game: drop discs into a seven-column board and make an unbroken line of four.',
 ['Choose computer or same-device play in Setup.','Tap a column to drop a disc. With Preview first enabled, tap again or press Drop to confirm.'],
 ['Check whether either player can win on the next move before building a longer plan.','Central columns take part in more potential lines; avoid giving your opponent a winning landing square.'],
 ['The board has seven columns and six rows. Players alternate, dropping one disc into any non-full column. It settles in that column’s lowest empty square. A placed disc cannot be moved or removed.','The first line of four or more of your discs horizontally, vertically or diagonally wins immediately. If the board fills without a line, the game is a draw. A full column cannot be selected. Setup chooses the starting player.','On a keyboard, use 1–7 for a column, or focus a column and activate it with Enter. Undo and hints are learning tools, not additional legal moves.']),
 draughts:make('English draughts on an 8 × 8 board. Capture or block every opposing piece to win.',
 ['Choose your colour, opponent and starting player in Setup.','Tap a movable piece, then a highlighted destination. For multiple captures, keep choosing the same piece’s next landing.'],
 ['Check compulsory captures before planning an ordinary move.','Keep pieces supporting each other and work toward the far row to gain kings.'],
 ['Each side begins with twelve men on the dark squares. Players alternate turns; only dark squares are used. A man moves one diagonal square forward to an empty square. A king moves one diagonal square forward or backward; kings do not slide across several squares.','Capture by jumping an adjacent opponent diagonally into the empty square immediately beyond, removing the jumped piece. Men capture forward only; kings capture both ways. If any capture is available anywhere, an ordinary step is illegal.','A capture must continue with the same piece until no further jump is available. When several captures or branches exist you may choose any legal sequence; there is no requirement to take the largest number. A man reaching the far row becomes a king and its turn ends, including during a capture.','Win when the opponent has no legal move, whether because all their pieces were captured or the remaining pieces are blocked. The app draws automatically on a third occurrence of a position or after forty moves by each side without a capture or a man moving. Setup can change who starts.'], 'English draughts · app adjudication', 'https://wcdf.net/rules/rules_of_checkers_english.pdf'),
 sudoku:make('Complete a number grid using row, column and box constraints, without changing its starting clues.',
 ['Choose a size and difficulty in Setup and request a new puzzle.','Tap an empty cell, then a number. Notes records possibilities; Erase clears a non-given cell.'],
 ['Begin with a row, column or box that has few empty cells.','Eliminate candidates using all three units that meet a cell; a repeated digit is a conflict, not a valid solution.'],
 ['For a board of size N, every row, every column and every outlined box must contain each number 1–N exactly once. The 6 × 6 and 12 × 12 grids use rectangular boxes; follow the heavy outlines. There is no extra diagonal constraint.','Starting clues are fixed. A completed solution must obey every unit, not just have no empty cells. Pencil notes do not count as entries and need not all be filled or erased to solve the puzzle.','The app marks duplicate entries as you type. Check also compares entries with the stored solution, so it can identify a wrong digit before it creates a visible duplicate. Hint distinguishes an explanation from a reveal. These aids do not add new puzzle rules.','Use arrows to move focus, Delete to erase, N to toggle notes, and Shift plus a number for a temporary note. On 12 × 12, A, B and C enter 10, 11 and 12. The puzzle clock pauses while you are away or using a modal.']),
 chess:make('A two-player strategy game. Protect your king and checkmate the opposing king; taking the king is never a legal move.',
 ['Choose an opponent and your colour in Setup. White starts.','Tap a piece, then a legal destination. For castling, select the king and its rook; choose a promotion piece when prompted.'],
 ['Develop knights and bishops, control central squares, and make your king safe.','Before moving, check your opponent’s forcing checks and captures, and what your move leaves unprotected.'],
 ['White moves first; players then alternate one move each on the 8 × 8 board. A move normally takes a piece to an empty square or captures an opposing piece on its destination. You may never leave your own king attacked.','Rooks slide along ranks or files, bishops along diagonals, and queens in either direction, stopping before friendly pieces and after capturing. Knights jump in an L: two squares along one axis and one along the other. Kings move one square in any direction to a square not attacked.','Pawns advance one empty square toward the far rank, or two from their starting rank if both squares are clear. They capture one square diagonally forward. Immediately after an opposing pawn advances two squares past an adjacent pawn, that adjacent pawn may capture it en passant as though it had advanced one. A pawn reaching the last rank must promote to a queen, rook, bishop or knight.','Castling moves the king two squares toward its original rook and brings that rook to the square the king crossed. Neither may have moved, the intervening squares must be empty, and the king may not start in check, cross an attacked square or finish on one.','Check means the king is attacked; the next move must remove it by moving the king, capturing the attacker or blocking the attack when possible. Checkmate is check with no legal reply and wins. Stalemate is no legal move without check and draws.','This app automatically draws at threefold repetition, fifty moves by each player without a pawn move or capture, and recognised insufficient-material or dead positions. These are automatic app adjudications; tournament claim procedures and clocks are not implemented. Board flip, attack highlights and the tutor are optional aids.'], 'Standard piece movement · automatic app draws', 'https://handbook.fide.com/chapter/e012023'),
 go:make('Place stones on intersections to surround more area than your opponent, while keeping your groups alive.',
 ['Choose 9 × 9, 13 × 13 or 19 × 19 and an opponent in Setup. Black starts.','Tap an empty intersection. If Preview first is on, confirm the preview. Inspect groups to see liberties; pass when no useful play remains.'],
 ['Keep groups connected and avoid filling your own liberties without a reason.','At scoring, inspect dead groups together; use Resume if the position is still disputed.'],
 ['Black and White alternate placing one stone on an empty intersection or passing. Stones do not move after placement. Orthogonally adjacent stones of the same colour form a group; its liberties are adjacent empty intersections. Diagonal contact does not join groups.','After a placement, opposing groups with no liberties are removed. Your new group must then have a liberty, so suicide is illegal unless the capture creates a liberty. Positional superko prohibits a placement that repeats any earlier board position, not merely the immediately previous position. Passing is allowed even though the board stays the same.','Two consecutive passes open score review. Tap a group to mark or unmark all its stones as dead, then confirm the score. Dead stones are removed for counting. Resume returns to play if life and death have not been agreed.','This app uses area scoring: living stones plus empty regions bounded only by that colour. Shared empty regions are neutral. White receives 7.5 komi. Captures are displayed but are not added again as prisoner points. The larger total wins; the app does not use Japanese territory scoring, pass stones or a handicap-placement procedure.'], 'Area scoring · positional superko · White komi 7.5'),
 blackjack:make('Play a hand against the dealer, aiming closer to 21 without going over. Chips are local game counters.',
 ['Set a bet you can afford and tap Deal.','For the active hand choose Hit, Stand, Double or Split when available. The dealer plays after your hands finish.'],
 ['Consider the dealer’s upcard rather than trying to reach 21 on every hand.','Use the tutor to learn why a decision changes with a soft total or a pair.'],
 ['A six-deck shoe is reshuffled before a deal when fewer than eighty cards remain. Number cards count their rank, face cards ten, and Aces one or eleven, whichever gives the highest total at most 21. A total using an Ace as eleven is soft.','Each deal gives you two cards and the dealer two, with one dealer card concealed during your decisions. An unsplit two-card Ace plus a ten-value card is a natural blackjack. Initial naturals are checked immediately; equal naturals push, otherwise a natural beats an ordinary 21.','Hit takes a card; Stand keeps the total. Going over 21 loses that hand immediately. Double is allowed on any first two cards except split Aces if you can match the stake: the bet doubles, you take exactly one card and stand.','Split requires two equal ranks, another stake and fewer than four total hands. Each new hand gets one card. Non-Ace pairs may be resplit within the four-hand limit; split Aces receive one card each and stand, and cannot be resplit. A 21 after splitting is an ordinary win, not a natural. Doubling after a non-Ace split is allowed.','The dealer hits below 17 and stands on every 17, including soft 17. A non-busted hand wins if the dealer busts or its total exceeds the dealer’s; equal totals push. A normal win profits one stake; natural blackjack profits 3:2; a push returns the stake. There is no insurance, surrender or five-card bonus.']),
 patience:make('Three solitaire games share one table: Klondike, FreeCell and Spider. Their building and movement rules differ.',
 ['Choose a variant in Setup. Klondike also offers draw-one or draw-three; Spider offers one, two or four suits.','Tap a card or legal run, then its destination. Draw or Deal advances the stock. Larger cards and Pan board help on phones.'],
 ['Expose hidden cards and create useful empty space before sending every card home.','In FreeCell, preserve empty cells; in Spider, build same-suit runs so they can move together.'],
 ['Klondike: one 52-card deck is dealt into seven tableau columns of one through seven cards, with only their top cards face up. The remainder forms a face-down stock. Build four foundations from Ace to King in suit. Build tableau downward in alternating red and black; move a face-up descending alternating-colour run as a unit. Only a King or a King-led run may fill an empty column. Exposing a face-down top card turns it face up.','Klondike stock: Draw turns over one or up to three cards according to Setup; only the top waste card is playable. When stock empties, recycle the waste without shuffling. Redeals are unlimited. Foundation tops may move back to the tableau. Win by putting all 52 cards on the four foundations.','FreeCell: deal all 52 cards face up into eight columns, with four single-card free cells. Foundations build Ace to King in suit; tableau builds down in alternating colours. Any card may fill an empty column. A run move is legal only when equivalent single-card moves are possible: capacity is (empty free cells + 1) × 2^usable empty columns. If the destination column is empty, it is not counted as temporary storage. Cards placed on foundations cannot return to play. Win by completing the foundations.','Spider: use 104 cards in ten tableau columns; initially 54 are dealt, with only the top card of each column face up. Build down by rank regardless of suit, but move a multiple-card run only when it is descending in one suit. Any card or movable run may fill an empty column. A complete same-suit King-to-Ace run is removed automatically.','Spider stock deals one card onto every column and requires every column to be occupied first. Choose one, two or four suits; every completed run must still be a single suit. Complete eight runs to win. Spider starts at 500 points, deducts one per move or stock deal with a floor of zero, and adds 100 for each completed run. Stock deals and their automatic completions undo together.','Auto-home, hints, Undo and Restart are aids. Klondike scoring starts at zero: newly exposed tableau cards earn 5, waste-to-tableau moves 5, cards sent to a foundation 10, foundation-to-tableau moves cost 15 and recycling the waste costs 20, with a floor of zero. The winning condition is foundation completion, not a target score.']),
 poker:make('A heads-up fixed-limit chip game against the computer, with Hold’em, Omaha and Five-card Draw.',
 ['Choose a variant in Setup and tap Deal.','Use Check, Call, Bet/Raise or Fold as offered. In Draw, select zero to five cards to exchange when prompted.'],
 ['The price of calling matters as well as your hand’s strength.','Omaha requires exactly two private cards; do not evaluate it using Hold’em’s any-five rule.'],
 ['Both players start a new table with 500 chips. A standard 52-card deck is shuffled for each hand; the dealer alternates. The better five-card poker hand wins at showdown, or the remaining player wins immediately when the other folds. All chips are virtual.','Hold’em: each player receives two private cards. The dealer posts the 5-chip small blind and the opponent the 10-chip big blind; the dealer acts first before the flop. Three community cards form the flop, then one the turn and one the river, with betting after each. After the flop, the nondealer acts first. Use the best five of the seven available cards, including zero, one or two private cards.','Omaha: receive four private cards; dealing, blinds and streets follow Hold’em. A final hand must use exactly two private cards and exactly three community cards. There is no high/low split.','Five-card Draw: each player antes 5 and receives five private cards. Nondealer acts first. A betting round is followed by one simultaneous exchange of zero to five selected cards, then a second betting round and showdown. There are no community cards.','Check stays in without betting when nothing is owed. Call matches the amount owed, Fold concedes, and Bet/Raise increases the price. Fixed increments are 10 on preflop/flop or the first Draw round and 20 on turn/river or the second Draw round. There are at most three raises per betting round. An opening bet is not a raise; the posted big blind already makes a preflop increase a raise.','Bets are capped at the chips both players can contest. Unmatched contributions are refunded; there are no multi-player side pots. Community cards run out automatically after an all-in. Tied five-card hands split the pot; any odd chip goes to the nondealer. Suits do not break ties.','Ranks, strongest first: straight flush (a royal flush is its highest form), four of a kind, full house, flush, straight, three of a kind, two pair, one pair, high card. Aces are high except in A-2-3-4-5, the lowest straight; they cannot wrap Q-K-A-2-3. Compare the made group first, then remaining kickers in descending order; flushes and high-card hands compare all five ranks.','The match cannot deal another hand when a stack is empty; start a new table to reset stacks. Tutor estimates use your known cards and unseen possibilities, not knowledge of the opponent’s hidden hand.']),
 mines:make('Open every safe square without opening a mine. Number clues describe the eight surrounding squares.',
 ['Choose a minefield size in Setup and open a square.','Switch Flag mode on a phone before marking suspected mines; switch it off to open squares.'],
 ['A revealed 1 with only one unopened neighbour identifies that neighbour as a mine.','Use chord-opening only when you trust your flags: the app checks their count, not their truth.'],
 ['Mines are placed when you make your first opening, excluding that square and its surrounding neighbourhood. Opening an empty zero expands nearby safe cells automatically. A numbered square counts mines among its up to eight horizontal, vertical and diagonal neighbours.','Opening a mine loses. Open all non-mine squares to win; flags are reminders and are not required for victory. A flag prevents an accidental ordinary opening until removed.','Activate a revealed number with exactly that many flags beside it to open its other unflagged neighbours. Incorrect flags can make this chord action explode a mine. The flag counter can be negative if you mark too many squares.','Use right-click or Flag mode to toggle flags; arrows move keyboard focus, Enter opens and F flags. Enlarging an expert board makes its cells tappable; Pan board moves the view without opening cells.']),
 life:make('Explore Conway’s cellular automaton, or compete in the app’s two-colony variation using the same birth and survival counts.',
 ['Choose a sandbox or colony mode. In the sandbox, paint cells or stamp a pattern, then Run or Step.','In colony play, make up to three cell edits, then End turn to advance one generation.'],
 ['Start with a blinker or glider and watch how simultaneous updates change it.','In colony play, consider what survives the next generation rather than only your current cell count.'],
 ['Every cell has eight neighbours, including diagonals. All cells update simultaneously from the previous generation: a live cell survives with two or three live neighbours; an empty cell is born with exactly three; all other cells are empty next generation. This is B3/S23.','With bounded edges, positions outside the grid are empty. With wrap-around, opposite edges are neighbours. Sandbox modes have no win condition: edit, step, run, pause, reset or bookmark a world. Colour does not change the birth/survival counts.','Colony mode starts with two coloured populations, Colony 1 first. On a turn you may toggle up to three cells: an occupied cell is removed, and an empty one becomes your colour. You may end a turn with unused edits. One generation then runs and the turn changes.','Survivors keep their colour; births take the majority colour of their three parents. Eliminating the other population wins; if both disappear the game draws. At generation 200 the larger population wins, with equal populations drawing.']),
 ski:make('Steer downhill through trees, rocks, gates and ramps, with endless Free ski and two 1,000-metre courses.',
 ['Choose Free ski, Slalom or Freestyle in Setup and start the countdown.','Use the left/right touch controls or arrow keys to steer; hold Brake to stop on the snow, and Jump to leap. Fast increases speed.'],
 ['Brake before a tight gate rather than making a last-second sideways sweep.','For a high jump, use a ramp; a low ordinary jump cannot clear every obstacle.'],
 ['The skier moves downhill automatically while skiing. Steering changes lateral movement. Brake slows and can stop the skier when grounded; release it to continue. Crashes cause a temporary tumble and remove 50 score points, with a floor of zero. Clearance depends on actual jump height.','Free ski has no finish line. After 2,000 metres a yeti pursues the skier; being caught ends the run. React to its approach and pounce rather than assuming straight-line speed alone will escape it.','Slalom ends at 1,000 metres. Pass through the marked gates: each clean gate earns 50 points and each missed gate adds three seconds to the final recorded time. Freestyle also ends at 1,000 metres and aims for a high score. Successful landings earn 100 points plus 100 for every completed half-spin of credited airborne lateral movement. Crashing prevents landing credit.','An ordinary jump and a ramp jump have different height and duration. A ramp starts the jump with one full spin of credit. Space jumps, F toggles Fast, P pauses, and either up or down arrow brakes. Runs pause when you leave the game or hide the tab, and resume with a short countdown.']),
 tetravex:make('Fit numbered square tiles into a grid so every pair of touching edges agrees.',
 ['Choose a 2 × 2, 3 × 3 or 4 × 4 puzzle in Setup.','Tap a tray or placed tile, then a destination. A selected placed tile can return to the tray.'],
 ['A locally matching tile may still prevent a complete solution.','Look for edge numbers that have few possible partners; use Undo if a promising arrangement reaches a dead end.'],
 ['Each tile has fixed north, east, south and west numbers. Fill every board position, matching east to west and south to north on all touching pairs. Outside edges are unconstrained, and tiles cannot rotate or flip.','Use every tile once. Tiles may be rearranged between the tray and board; a mismatch cannot be committed through normal play. Highlighted destinations indicate local legality, not a promise that the rest of the puzzle can be solved.','Hint searches around current placements. Undo removes a previous action; neither time nor move count changes which complete arrangements are valid.']),
 noughts:make('A two-player game on nine squares: make a line of three marks before your opponent.',
 ['Choose a computer level or same-device play in Setup.','Tap an empty square on your turn. Crosses start.'],
 ['Take an immediate win, and block the opponent’s immediate win.','A fork threatens two winning lines at once; the centre participates in four lines.'],
 ['The board is 3 × 3. Players alternate placing one mark on an empty square: crosses first, then noughts. Placed marks cannot be moved.','Three of your marks in a row, column or diagonal wins immediately. If all nine squares fill without a winning line, the result is a draw. Perfect play can force a draw; the level-5 computer does not deliberately make mistakes.']),
 reversi:make('Bracket and flip opposing discs, finishing with more discs on the board than your rival.',
 ['Black starts from the standard four-disc centre. Choose an opponent in Setup.','Tap a highlighted legal square. The app flips every bracketed line and automatically passes a player who has no move.'],
 ['Corners cannot later be flipped and are valuable anchors.','Avoid giving away a corner just to gain many discs early; keep useful legal moves available.'],
 ['Play on an 8 × 8 board. A legal placement must bracket at least one uninterrupted line of opposing discs between the newly placed disc and an existing disc of your colour. Lines may be horizontal, vertical or diagonal.','Flip all such bracketed lines created by the placement; you may not choose to flip only some. Your existing discs do not trigger additional chain reactions after those flips.','A player with no legal move must pass; passing voluntarily when a move exists is not allowed. The game ends when neither player can move, even if empty squares remain. Most discs wins, with an equal count drawing.']),
 dots:make('A two-player edge-drawing game. Close boxes to claim them and earn another move.',
 ['Choose the board size and opponent in Setup.','Tap an unclaimed horizontal or vertical edge. Your colour marks boxes you complete.'],
 ['Avoid adding the third side of a box unless the exchange helps you.','Near the end, consider whole chains of boxes rather than one box at a time.'],
 ['Players take turns claiming one previously unclaimed edge between adjacent dots. Edges do not move and cannot be removed. Completing the fourth side of a box assigns that box to the player who drew the edge.','An edge can complete two boxes at once. Closing one or more boxes earns another turn; an edge closing none passes play to the opponent.','When all boxes are claimed, the player with more boxes wins. Equal box totals draw. The ownership of the earlier three edges does not affect who claims a completed box.']),
 morris:make('Place and move nine men to form mills, removing opposing men until they cannot continue.',
 ['Place your reserve men on empty marked points.','After placement, tap one of your men and a legal destination. Forming a mill prompts you to choose an opposing man to remove.'],
 ['Keep two possible mill threats available so your opponent cannot block both.','A mill can be opened and closed again on a later turn to earn another capture.'],
 ['Each player has nine men and alternates placing them on empty points of the 24-point board. A mill is a complete straight line of three connected points of your colour. There are no diagonal mills.','Once reserves are placed, move one man along a printed connection to an adjacent empty point. A player reduced to exactly three men may fly a man to any empty point.','Forming a new mill removes one opposing man. Choose a man outside an opposing mill if one exists; otherwise any opposing man may be taken. Forming two mills with one move still earns only one removal in this app.','After placement, having fewer than three men or no legal move loses. Threefold repetition or fifty moves by each side without a capture draws automatically.']),
 kalah:make('Sow seeds around two rows and collect them in your store. This table uses six pits per side with four seeds each.',
 ['Tap a nonempty pit on your side.','The app sows its seeds and indicates whether you play again. Stores hold scored seeds and are not selectable pits.'],
 ['Look for moves whose last seed lands in your store.','Count backward from an empty pit on your side to spot a capture opportunity.'],
 ['Players alternate choosing one nonempty pit from their own row. Lift all its seeds and sow them counterclockwise, one into each following pit and your store, skipping the opponent’s store. Sowing can continue around the board more than once.','A final seed in your store earns another turn. A final seed in an empty pit on your own side captures that seed and the seeds in its opposite pit, but only if the opposite pit is occupied. Put captured seeds in your store. A capture alone does not earn another turn.','As soon as either row is empty, each player sweeps the seeds remaining on their own side into their own store. The larger store wins; equal stores draw.']),
 backgammon:make('Race fifteen checkers home and off the board while hitting and blocking the opponent, with an optional doubling cube.',
 ['Roll the opening dice; a tied opening is rerolled.','Tap a checker, then a legal destination using a remaining die. Roll again when your next turn begins.'],
 ['Protect vulnerable single checkers by making points with two or more.','Before bearing off aggressively, consider whether a hit could put you back on the bar.'],
 ['Each side starts with fifteen checkers in the standard arrangement. Player 1 moves from point 24 toward 1; Player 2 moves in the opposite direction. The opening roll gives one die to each player; the higher roller starts and uses both dice.','Each die moves one checker by its number, and one checker may use several dice in separate legal steps. Doubles provide four uses of that number. You must use as many dice as possible; if only one of two distinct dice can be used, you must use the higher one whenever possible. Intermediate landings must also be legal.','A point with two or more opposing checkers is blocked. Landing on a single opposing checker hits it onto the bar. All your bar checkers must re-enter on the opponent’s home board, using legal dice, before any other checker can move. If no move is possible, unused dice are lost.','When all your checkers are in your own six home points, bear them off with exact dice. An oversized die may remove a checker only when there is none farther from bearing off. First to bear off all fifteen wins.','A win is a single if the opponent has borne off any checker, a gammon if they have borne off none, or a backgammon if they have borne off none and still have a checker on the bar or in the winner’s home board. These score one, two or three times the cube value.','The cube starts at 1. Before a normal roll, its owner or either player while it is centred may offer to double. Accepting doubles its value and gives ownership to the recipient; declining ends the game at the current value. This table scores individual games, without tournament match or Crawford rules.']),
 mahjong:make('A solitaire tile-matching puzzle. Remove matching free tiles until the layout is empty.',
 ['Choose a layout in Setup.','Tap one free tile, then a matching free tile. Selectable tiles are highlighted; use Enlarge for dense layouts.'],
 ['Free tiles that unblock long rows or lower layers are often useful early choices.','When several identical tiles are available, compare what each possible pair would uncover.'],
 ['A tile is free only if no tile overlaps it from above, even partially, and at least one of its horizontal sides is clear. Both selected tiles must be free at the time of removal.','Ordinary tile faces must match exactly. Any flower may match another flower, and any season another season; flowers do not match seasons. This is solitaire matching, without Mahjong hands, calls, winds or gambling scores.','Remove every tile to win. A deal begins with at least one complete removal solution, but choices can still block the remainder. Undo reverses a removal; the undoable Shuffle rearranges remaining tiles when you want another chance.']),
 sliding:make('Slide numbered tiles into reading order, leaving the empty square at the bottom right.',
 ['Choose a grid size in Setup and shuffle a new puzzle.','Tap a tile sharing an edge with the empty square. It slides into that square.'],
 ['Place the early rows while preserving room to manoeuvre the later ones.','A useful temporary detour can increase distance from the goal; a hint need not be a shortest solution.'],
 ['There is one empty square. A move swaps it with one orthogonally adjacent tile. Diagonal moves, jumps and wrapping across the board edge are not allowed.','The goal is ascending reading order, left to right and top to bottom, with the empty square last. All generated shuffles come from legal moves, so they are reachable.','Arrow keys move the empty square. Undo takes back a slide. The hint search is bounded on distant positions and may suggest a useful detour; it does not promise the minimum number of moves.']),
 pegs:make('A solitaire jumping puzzle. Remove pegs one at a time and aim to leave a single peg.',
 ['Choose the board layout, then tap a peg.','Tap an empty socket two positions away along a horizontal or vertical line when the middle socket contains a peg.'],
 ['Work backward from the peg you want to leave at the end.','Avoid isolating a peg at an edge where no later jump can reach or use it.'],
 ['A legal move jumps one peg over an adjacent peg into the empty socket immediately beyond. Remove the jumped peg; the jumping peg remains in its destination. Every move removes exactly one peg.','Only horizontal and vertical jumps are allowed. All three sockets must exist in the chosen board shape. There are no diagonal jumps or jumps over two pegs.','The puzzle ends when no jump remains. One remaining peg is a success; finishing at the centre is a stronger personal goal, not a separate capture rule. Undo and hints let you explore another route.']),
 nonograms:make('Use row and column clues to uncover a picture of filled and empty squares.',
 ['Choose a picture in Setup.','Use Fill, Cross or Erase and tap or drag over cells. A cross records a known empty square.'],
 ['A run longer than half its line has overlapping cells that must be filled.','After finishing a run, mark its separating empty squares before working on the next run.'],
 ['Each clue lists the lengths of consecutive filled runs in that line, in order. Leave at least one empty square between consecutive runs; more empty squares may appear before, between or after them. A clue of zero means that line has no filled cells.','Row and column clues must hold simultaneously. Crosses are notes for empty squares; unfilled cells need not all be crossed to complete the actual picture.','Right-click marks a cross. Check reports conflicts with the stored picture; a correcting reveal is identified as such rather than presented as a deduction. Hints may explain a forced square.']),
 cribbage:make('A two-player card game of pegging and hand combinations. Reach 121 points before the computer.',
 ['Select two of your six cards and send them to the dealer’s crib, then cut the starter.','Play a legal card during pegging, or Go only when none fits. Review the automatic hand counts afterward.'],
 ['Choose discards with both your four-card hand and ownership of the crib in mind.','During pegging, watch for 15, 31, pairs and the trailing run, rather than only the running total.'],
 ['Use a standard 52-card deck. Deal six cards each; both players discard two to the dealer’s four-card crib. Cut a common starter. If it is a Jack, the dealer immediately scores two. Dealer alternates between hands.','Nondealer leads pegging. Alternate playing cards without raising the running total above 31; Aces count 1, faces 10 and others their rank. A total of 15 or 31 scores two. Consecutive equal ranks score 2 for a pair, 6 for three and 12 for four. A run in the trailing cards scores its length even when played out of order, provided the run has no repeated rank.','Go is allowed only when no held card fits below or at 31. The other player continues while able. The last card below 31 scores one; there is no additional last-card point at exactly 31. Reset the count after 31 or both players being unable to play; the player after the last card leads the next count.','Then count nondealer’s hand, dealer’s hand and the crib, each with the starter. Every distinct combination totalling 15 scores two, every pair two, and longest runs score their lengths, including multiple runs created by duplicate ranks.','A four-card same-suit hand scores four for its flush, or five if the starter shares the suit. A crib flush scores only when all five cards share a suit. One for his nob scores for a held Jack matching the starter’s suit. Aces are low for runs.','The app scores automatically with no muggins claim. First to 121 wins immediately, including during pegging or the starter bonus, so later counts may not occur.']),
 snake:make('Guide a growing snake to apples without colliding with its body or the field boundary.',
 ['Choose speed and whether edges wrap in Setup, then Start.','Swipe on the board, tap a direction control, or use arrows/WASD to turn.'],
 ['Leave an escape route behind the head rather than chasing every apple by the shortest route.','A direction directly back into the neck is ignored; plan a perpendicular turn first.'],
 ['The snake moves one cell at a time in its current direction. Eating an apple grows it and awards 10 + twice the selected speed level in points; a new apple appears on a free cell.','Entering the snake’s occupied body ends the run. Entering the cell the tail vacates on a non-growing move is safe. With wrap-around off, crossing an edge loses; with it on, the snake re-enters at the opposite edge. Filling the board completes the run.','Speed and wrapping apply to a new run. Space or P pauses, Enter starts or resumes. Swipes change direction while the finger moves, rather than waiting for release.']),
 blocks:make('Arrange falling tetrominoes into complete horizontal rows, with Marathon, Sprint, Ultra and Zen modes.',
 ['Choose a mode in Setup and Start.','Use the touch buttons or keyboard to move, rotate, Hold and Drop. The ghost shows where a hard drop lands.'],
 ['Keep the surface manageable and avoid covering holes with more pieces.','Use Hold once per piece when it improves the shape you are building; leave space for the next piece to spawn.'],
 ['Seven tetromino shapes enter from a shuffled seven-piece bag. Move and rotate an active piece without crossing the walls or settled blocks. It falls automatically except in Zen. A grounded piece normally locks after 500 ms, with at most fifteen movement/rotation resets of that delay. Completed full rows disappear and the rows above fall into the cleared space.','Hard Drop lands and locks immediately; Soft Drop accelerates descent. Hold stores the current shape or swaps with the held shape and may be used only once before the next lock. Rotation uses the game’s wall-kick tests; it cannot pass through occupied cells.','Marathon continues with faster falling every ten lines. Sprint finishes at forty cleared lines and measures time. Ultra lasts two minutes and measures score. Sprint and Ultra stay at level 1; pauses and countdowns do not count toward their time. Zen has no gravity or automatic lock delay; place pieces at your own pace. A blocked spawn or blocks left in the hidden top rows after a lock ends a run.','Normal clears award 100, 300, 500 or 800 times the current level for one to four lines. A recognised T-spin awards 400, 800, 1,200 or 1,600 times level for zero to three lines. This game recognises a T-spin when the last action was a rotation and at least three corners of its 3 × 3 area are occupied or out of bounds.','Consecutive difficult line clears (quads or T-spins) get a 1.5 multiplier; a non-difficult line clear breaks that chain. Successive line-clearing pieces add a 50 × combo × level bonus. A perfect clear adds 2,000 × level. Soft-drop cells add one point and hard-drop cells two.','Keyboard: left/right move, down soft-drops, up or X rotates clockwise, Z rotates anticlockwise, Space hard-drops and C or Shift holds. The displayed Controls panel includes the available key bindings and handling settings.']),
 salvage:make('Pilot an armed salvage ship through six sectors, clearing raider waves and collecting archive cores to rebuild the archive.',
 ['Launch the patrol, steer with the on-screen stick or WASD/arrows, and hold Fire to shoot forward.','Follow the objective tracker, collect glowing loot, then use the between-sector workshop to upgrade and continue.'],
 ['Turn the ship’s nose toward a target before firing; steering is relative to the ship.','Use EMP when enemies or projectiles are in front, and save some weapon energy instead of firing blindly.'],
 ['The current arcade expedition contains six sectors with three waves each. Destroy hostile ships and required carriers, crack supply caches and collect enough archive cores to clear each sector. Cores bank immediately in the arcade expedition; once a sector is clear, remaining cores are pulled in and the upgrade break opens.','Up/W accelerates forward, Down/S brakes, Left/Right or A/D turns. The stick has the same ship-relative controls. Space or left-click fires the main gun; E, right-click or EMP fires the directional secondary weapon. Shift boosts, F extends the magnet and R toggles continuous forward fire.','Main weapons draw energy, have different firing rates and can be selected with 1–3. The directional EMP has a separate recharge. Pickups can restore hull, shields or energy, award credits, or grant temporary combat/collection boosts. Credits buy engine, weapon, shield and tractor upgrades at the workshop.','Incoming damage consumes protection and can reduce hull to zero, disabling the ship. Retry restores a viable ship while keeping the arcade expedition’s banked loot and progress; New expedition starts over. Finishing all six sectors completes the expedition.','Older saved recovery patrols can include cargo delivery to a relay, survey beacons and courier objectives. In that format, follow the mission briefing and dock near the relay to bank cargo, repair and advance after required objectives. IFF safety prevents friendly fire; disabling it can provoke the wardens.']),
 void:make('Build a fighter through a thirty-wave expedition, docking for upgrades every two waves and defeating the final core fleet.',
 ['Choose a difficulty and fighter in the hangar, then launch or Continue a saved docked run.','On a phone, steer with the right stick and hold Fire on the left. Dash, Shockwave and fitted cluster rockets have separate buttons.'],
 ['Keep a route through enemy fire rather than staying still to maximise shots.','Use Ship & Repair at resupply, and compare the next rank’s effect with the price before buying.'],
 ['The expedition has three acts and thirty waves. Survive the timed fighting phase, clear remaining hostiles and defeat commander encounters when they occur. After each even completed wave, a resupply beacon lets you dock; reach it or use Dock when available. The final wave is a fleet encounter rather than an ordinary shop break.','Move with WASD/arrows or the right stick. Hold Space or Fire to shoot; F toggles autofire. Shift dashes in the movement direction, E/Q releases a fully charged shockwave, and R launches a fitted cluster rocket. A dash briefly protects you and has a recharge; shockwave charge comes from time and combat.','Deflector protection absorbs damage before hull where applicable. Hull reaching zero ends the flight. Collect credits, crates and temporary bonuses. Weapon upgrades, missile upgrades, rapid fire, speed, shields and magnet ranks change the installed build; displayed limits and costs control purchases.','Docking pauses combat, refills ordnance and saves an expedition checkpoint. Buy upgrades you can afford, repair missing hull for the displayed cost, or confirm salvage to remove all purchased ranks of that item for 60% of their paid cost. Mobile Ship & Repair separates the loadout and repair from the catalogue. Launch next wave continues combat.','Each fitted cluster pod has three rockets per dock; each rocket bursts into sixteen friendly homing seekers. Left and right pods are separate fittings. Shockwave, dash, ordnance and shop controls are enabled only when their charges and current phase allow them.','Continue restores the latest resupply checkpoint, including credits, hull and build. Practice lets you select a starting wave and loadout without replacing the expedition save or earning normal career progress. Completing the campaign can continue into Endless; a normal campaign victory is defeating wave thirty.']),
 whacker:make('A quick-reaction garden game: hit awake guests, avoid sleepy ones, and build an accurate streak.',
 ['Choose a guest, difficulty and Timed or Practice in the Party/setup panels.','Start, then tap an awake character when it has risen. Custom guests can be imported from PNG or JPG images.'],
 ['Watch for sleepy guests instead of sweeping every hole.','Accurate consecutive hits increase the multiplier; waiting for a good target can beat repeated random taps.'],
 ['There are nine holes. Guests rise, remain briefly hittable and then leave. A normal guest awards 10 base points, a party guest 20 and a crowned guest 30, multiplied by the current streak multiplier and any fever bonus. Sleepy guests must be left alone.','Every five consecutive successful hits raises the multiplier, up to ×4. Every fifteenth consecutive hit can start six seconds of fever, doubling hit points. Hitting an empty hole or a sleepy guest, or letting an awake target escape, breaks the streak. A sleepy hit also removes 20 points, with a floor of zero.','The one- or two-attempt setting gives a board-wide allowance between new pop-ups or successful hits. Misses consume it and briefly delay another attempt; rejected early or excess taps are ignored, not queued. A successful hit refreshes the allowance, allowing another ready guest to be hit immediately.','Timed lasts sixty seconds, with the selected difficulty controlling pop-up pace and crowding; the goal is a high score. Practice has no time limit and does not ramp with elapsed time. Pause freezes the round. Custom images change the guest’s appearance, not scoring or the sleepy rule.']),
 horizon:make('Fly a neon city in a timed intercept mission, an endless battle, a guided flight school or a relaxed cruise.',
 ['Choose a mode and control method in the hangar. Flight school teaches turning, levelling, braking, firing, boost, gates and EMP.','Use the selected stick, mouse or keyboard scheme; on touch, use the steering stick and separate Fire, Brake, Boost, Level and EMP buttons.'],
 ['Make small corrections and aim at the target’s lead marker rather than directly at a fast-moving target.','Brake to line up a gate or turn; reserve energy for an escape boost or EMP.'],
 ['Mission progresses through three sectors: destroy six scouts, then eight hostiles, then the Sentinel command ship before the mission timer expires. Running out of mission time or losing the ship ends the attempt; completing the final encounter wins and awards a remaining-time/shield bonus.','Steering controls yaw and pitch. Level recovery settles pitch and bank while keeping heading, but steering input can override it. Fire shoots forward; a moving target’s lead marker helps aim. Flight school uses staged objectives instead of the mission victory condition.','Boost drains the shared energy reserve; release it to recharge. EMP requires 45 energy and its cooldown, clears nearby hostile shots and disrupts enemies. Recharge gates restore 18 shields and 55 energy, award 150 × multiplier points and, in Mission, add five seconds each up to thirty extra seconds in total. Collisions and enemy fire damage the ship outside protected practice/cruise rules.','Kills chained within seven seconds build a multiplier up to ×4. Damage or an expired chain resets it. Kills restore three shields, or fifteen for a boss; after six seconds without damage, shields regenerate at two per second. Near misses, close bullet dodges and gates award extra points and energy.','Endless advances through continuing hostile encounters without a final mission victory. Practice and Cruise are forgiving: impacts grant brief protection instead of ending the run. Cruise is free flight rather than the timed three-sector contract.','In Keyboard mode, W/S pitches and A/D turns; arrows also steer. In the desktop-default Flight stick mode, centre the cursor to engage, then offset it to pitch/turn; W/S changes throttle and A/D strafes instead. Mouse mode uses mouse motion or dragging to aim, with click to fire and right-click for EMP. Q/E rolls, Space fires, Ctrl brakes, Shift boosts, R levels and F releases EMP. The minus/plus controls adjust throttle.','On touch, use the left steering stick and the named action buttons; automatic cannons can free your firing thumb. On a standard gamepad, the left stick steers, right stick rolls/changes throttle, RT fires, LT brakes, RB boosts, LB drifts, B releases EMP, X levels and Y changes view.']),
 ballistics:make('A turn-based artillery battle between rover squads on destructible terrain, with solo, local-versus and firing-range modes.',
 ['Choose a match or firing range, map and settings. Select an active rover before committing its action.','Move and aim with the touch controls. For charged projectiles, hold Fire to choose power and release to launch; targeted tools ask for a battlefield destination.'],
 ['Read wind before firing a projectile and leave room to retreat from your own blast.','A carefully placed terrain hit or a fall into lava can matter more than direct damage.'],
 ['Normal matches have two teams of three rovers, each starting with 100 hull. Teams alternate timed turns, rotating through surviving units; you may select another friendly unit before committing the turn’s action. Move using available fuel, jump, aim, choose equipment and attack before the timer expires. After an attack a short retreat phase lets the rover seek safety while the result resolves.','Explosions damage nearby rovers, including friendly units, and remove terrain. Falls and lava can destroy units. Eliminate every enemy rover to win; simultaneous elimination can draw. Wind changes projectile flight. Sudden death raises lava from the chosen round; occasional supply crates restore health or ammunition. The firing range is practice rather than a scored team match.','Bazooka has unlimited ammunition and explodes on impact. Grenade is unlimited, bounces and uses a selectable one-to-five-second fuse. Cluster has three uses and releases five small bombs. Laser has four uses, is blocked by terrain and is not affected by wind. Air Strike has one use: choose a column for five falling bombs.','Jetpack has two uses and gives powered movement for the turn. Teleport has two uses, requires a clear landing and commits the attack. Grapple has five uses: attach to terrain, swing, reel and release; it still allows an attack. Shotgun has three ammunition uses, each providing two separately aimed close-range shots. Dynamite has three uses and places a five-second charge beside the rover.','The weapon panel shows the full arsenal, remaining ammunition and contextual controls. Selecting a weapon alone does not fire it. Cancelling a charged shot does not launch it. Movement, aim, fuel and retreat remain subject to the turn phase and selected tool.']),
};

export const GAME_HELP:Record<HelpGame,GameHelp>={...nativeGuides,...Object.fromEntries(Object.entries(plusGuides).map(([id,guide])=>{const base=PLUS_RULES[id as PlusGame];return [id,{...guide,variant:base.variant,rules:[...base.rules,...(guide.extraRules??[])],source:base.source}];}))} as Record<HelpGame,GameHelp>;
const esc=(text:string)=>text.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
export function renderGameHelp(game:HelpGame){
 const h=GAME_HELP[game];
 return `<article class="game-help" data-help-game="${game}"><p class="help-game-name">${esc(GAME_NAMES[game])}</p><div class="help-contents" role="group" aria-label="Help sections">${['Introduction','Getting started','Tips','Full rules'].map((label,i)=>`<button type="button" data-help-jump="${i}">${label}</button>`).join('')}</div>${[
  ['Introduction',`<p>${esc(h.introduction)}</p>`],
  ['Getting started',`<ol>${h.gettingStarted.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`],
  ['Tips',`<ul>${h.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`],
  ['Full rules',`${h.variant?`<p class="help-variant">${esc(h.variant)}</p>`:''}${h.rules.map(t=>`<p>${esc(t)}</p>`).join('')}${h.source?`<p class="help-reference"><a href="${esc(h.source)}" target="_blank" rel="noopener noreferrer">Rules reference ↗</a> · The text above describes the version played in this app.</p>`:''}`],
 ].map(([heading,body],i)=>`<section data-help-section="${i}" aria-label="${heading}"><h2 tabindex="-1">${heading}</h2>${body}</section>`).join('')}</article>`;
}
